  padding: var(--v4-card-body-inset);
  padding-inline-start: calc(var(--v4-card-body-inset) + var(--v4-card-lead));
}
.cardHeader + .cardBody {
  padding-top: 0;
}
.cardPlain {
  background: var(--v4-surface);
}
.card[data-variant="framed"] {
  --v4-card-frame-pad: var(--v4-space-3);
  padding: var(--v4-card-frame-pad);
  background: var(--v4-tint);
  border: 0;
  border-radius: calc(var(--v4-radius-panel) * var(--corners));
}
.card[data-variant="framed"]:has(> .cardHeader) {
  padding-top: 0;
}
.card[data-variant="framed"] > .cardHeader {
  align-items: center;
  min-height: var(--v4-space-40);
  padding: var(--v4-space-4) var(--v4-space-12);
}
.card[data-variant="framed"] > .cardHeader .cardHeading {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--v4-muted);
  text-transform: uppercase;
  font-family: var(--v4-type-eyebrow-font-family);
  font-size: var(--v4-type-eyebrow-font-size);
  line-height: var(--v4-type-eyebrow-line-height);
  font-weight: var(--v4-type-eyebrow-font-weight);
  letter-spacing: var(--v4-type-eyebrow-letter-spacing);
}
.card[data-variant="framed"] > .cardHeader .cardTitleGroup {
  align-items: center;
  grid-row: 1;
}
.card[data-variant="framed"] > .cardHeader .cardAction {
  height: auto;
  color: var(--v4-text2);
