  animation-name: tipOut;
}
@keyframes popIn {
  from {
    opacity: 0;
    translate: var(--v4-pop-from);
    scale: 1 0.96;
  }
}
@keyframes popOut {
  to {
    opacity: 0;
    translate: var(--v4-pop-from);
    scale: 1 0.96;
  }
}
@keyframes tipIn {
  from {
    opacity: 0;
    translate: var(--v4-pop-from);
  }
}
@keyframes tipOut {
  to {
    opacity: 0;
    translate: var(--v4-pop-from);
  }
}
@keyframes fadeIn {
  from {
    opacity: 0;
  }
}
@keyframes fadeOut {
  to {
    opacity: 0;
  }
